  out.push({kind:spec.kind,points:[initial],input:initial,u,other:[1,0],current:x,cycle:0,phase:'Read input',title:'Two lines and a finite trajectory',why:'A full cycle applies the sloping projection, then the horizontal one.',note:'The plotted intersection is the origin; finite iterates need not equal it.',formula:'Cycle 0: x = '+vec(x),certificate:true});
  for(let cycle=1;cycle<=5;cycle++){const q=mat(Q,x),p=mat(P,q);out.push({kind:spec.kind,points:[initial,...out.slice(1).map(f=>f.current),q],input:initial,u,other:[1,0],previous:x,current:q,cycle,phase:'Apply Q',title:'Cycle '+cycle+': project onto the sloping line',why:'The current point moves perpendicular to the sloping line.',note:'One individual projection is half a full cycle.',formula:'Qx = '+vec(q),certificate:close(dot(u,sub(x,q)),0)&&norm(q)<=norm(x)+1e-9});out.push({kind:spec.kind,points:[initial,...out.slice(1).map(f=>f.current),q,p],input:initial,u,other:[1,0],previous:q,current:p,cycle,phase:'Apply P',title:'Cycle '+cycle+': return to the horizontal line',why:'Only the horizontal component of the sloping point is retained.',note:'The cycle is a product, not generally an intersection projector.',formula:'(PQ)^'+cycle+' b = '+vec(p),certificate:close(p[1],0)&&norm(p)<=norm(q)+1e-9});x=p;}
