  const y=sub(scale(z.p,2),z.b);return[0,1,2,3].map(i=>({...z,kind:spec.kind,stage:i,reflected:y,points:[z.b,z.p,y],title:['Read the reflecting line','Find the closest point','Reverse the normal component','Check the midpoint and length'][i],why:['Reflection fixes the line and reverses its perpendicular direction.','The projection is the midpoint between input and reflected output.','The residual changes sign while the fitted component stays fixed.','The reflection is reversible and preserves Euclidean length.'][i],note:metric,formula:'Hb = '+vec(y)+'; midpoint = '+vec(z.p),certificate:z.certificate&&close(norm(z.b),norm(y))&&eq(scale(add(z.b,y),.5),z.p)}));
