 if(f.kind==='plane'){
  const pos=v=>[225+55*(v[0]-v[1])/Math.sqrt(2),166-55*(v[0]+v[1]-2*v[2])/Math.sqrt(6)],tx=(x,y,t,cls='pr-prose')=>'<text x="'+x+'" y="'+y+'" class="'+cls+'">'+esc(t)+'</text>',arrow=(a,b,c,dash=false)=>{const x=pos(a),y=pos(b);if(norm(sub(a,b))<1e-10)return'';return'<line x1="'+fmt(x[0])+'" y1="'+fmt(x[1])+'" x2="'+fmt(y[0])+'" y2="'+fmt(y[1])+'" stroke="'+c+'" stroke-width="2.5"'+(dash?' stroke-dasharray="5 4"':'')+' marker-end="url(#'+id+'-'+c.slice(1)+')"/>';},colors=['#17636a','#b34a3c','#536b9c'];
  let s='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 330" role="img" aria-label="'+esc(f.title)+'"><defs>'+colors.map(c=>'<marker id="'+id+'-'+c.slice(1)+'" markerWidth="7" markerHeight="6" refX="6.5" refY="3" orient="auto"><path d="M0 0 L6.5 3 L0 6 Z" fill="'+c+'"/></marker>').join('')+'</defs><rect x="12" y="12" width="442" height="300" rx="8" fill="#f4f8f6" stroke="#ccdcd7"/><polygon points="'+[[-1,-1,-2],[2,-1,1],[2,2,4],[-1,2,1]].map(v=>pos(v).map(fmt).join(',')).join(' ')+'" fill="#d7ebe4" stroke="#91b7a8"/>';
  s+=tx(27,40,'Three-dimensional orthographic view')+arrow([0,0,0],f.b,'#536b9c');if(f.stage>=1)s+=arrow([0,0,0],f.p,'#17636a');if(f.stage>=2)s+=arrow(f.p,f.b,'#b34a3c',true);
  const labels=[['Input',f.b],...(f.stage>=1?[['Plane point',f.p]]:[]),...(f.stage>=2?[['Normal residual',f.r]]:[])];labels.forEach(([label,v],i)=>s+=tx(480,44+i*57,label)+tx(480,67+i*57,vec(v),'pr-math'));
  return s+tx(480,282,'Plane normal: (−1, −1, 1)','pr-math')+tx(480,303,'Certificate: verified')+'</svg>';
 }
 const points=[...(f.points||[]),[0,0]],extent=Math.max(2,...points.flatMap(x=>x.map(Math.abs)))*1.28,sc=118/extent,xy=v=>[225+v[0]*sc,164-v[1]*sc],pt=v=>xy(v).map(fmt).join(','),line=(a,b,color,width=2,dashed=false,arrow=false)=>{if(norm(sub(a,b))<1e-10)return'';return'<line x1="'+fmt(xy(a)[0])+'" y1="'+fmt(xy(a)[1])+'" x2="'+fmt(xy(b)[0])+'" y2="'+fmt(xy(b)[1])+'" stroke="'+color+'" stroke-width="'+width+'"'+(dashed?' stroke-dasharray="5 4"':'')+(arrow&&norm(sub(a,b))*sc>=12?' marker-end="url(#'+id+'-'+color.slice(1)+')"':'')+'/>';};
 const colors=['#17636a','#b34a3c','#536b9c'];let s='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 330" role="img" aria-label="'+esc(f.title)+'"><defs>'+colors.map(c=>'<marker id="'+id+'-'+c.slice(1)+'" markerWidth="7" markerHeight="6" refX="6.5" refY="3" orient="auto" markerUnits="strokeWidth"><path d="M0 0 L6.5 3 L0 6 Z" fill="'+c+'"/></marker>').join('')+'</defs>';
 const tx=(x,y,t,cls='pr-prose')=>'<text x="'+x+'" y="'+y+'" class="'+cls+'">'+esc(t)+'</text>';
 s+='<rect x="12" y="12" width="442" height="300" rx="8" fill="#f4f8f6" stroke="#ccdcd7"/>';s+=line([-extent,0],[extent,0],'#b0beba',1)+line([0,-extent],[0,extent],'#b0beba',1);s+=tx(27,40,'Coordinate plot · axes share one scale');
 const anchor=f.anchor||[0,0],u=scale(f.u,1/norm(f.u)),radius=extent*.88;s+=line(add(anchor,scale(u,-radius)),add(anchor,scale(u,radius)),'#17636a',2.5);
