const api={frames,projection,lineP,plot};if(typeof module!=='undefined'){module.exports=api;return;}globalThis.ProjectionModels=api;
function mount(host,spec){const data=frames(spec);let index=0,timer=null;const stage=host.querySelector('.pr-stage'),caption=host.querySelector('.pr-caption'),progress=host.querySelector('.pr-progress'),formula=host.querySelector('.pr-formula'),why=host.querySelector('.pr-why'),seek=host.querySelector('[data-seek]');const stop=()=>{clearInterval(timer);timer=null;host.querySelector('[data-play]').textContent='Play';};
 const show=i=>{index=Math.max(0,Math.min(data.length-1,i));const f=data[index];stage.innerHTML=plot(f);caption.textContent=f.title;why.textContent=f.why+' '+f.note;formula.textContent=f.formula;progress.textContent='Step '+(index+1)+' of '+data.length;seek.max=data.length-1;seek.value=index;host.dataset.frame=index;host.dataset.certificate=String(f.certificate);host.querySelector('[data-prev]').disabled=index===0;host.querySelector('[data-next]').disabled=index===data.length-1;};
 host.querySelector('[data-prev]').onclick=()=>{stop();show(index-1);};host.querySelector('[data-next]').onclick=()=>{stop();show(index+1);};host.querySelector('[data-reset]').onclick=()=>{stop();show(0);};seek.oninput=()=>{stop();show(Number(seek.value));};host.querySelector('[data-play]').onclick=()=>{if(timer){stop();return;}if(index===data.length-1)show(0);host.querySelector('[data-play]').textContent='Pause';timer=setInterval(()=>{show(index+1);if(index===data.length-1)stop();},1600);};
 host.addEventListener('keydown',e=>{if(e.target.matches('input,select'))return;if(e.key==='ArrowRight'){e.preventDefault();stop();show(index+1);}if(e.key==='ArrowLeft'){e.preventDefault();stop();show(index-1);}});
 host.querySelector('.pr-print').innerHTML=[0,data.length-1].map(i=>'<figure>'+plot(data[i])+'<figcaption>'+esc(data[i].title+' '+data[i].why+' '+data[i].formula)+'</figcaption></figure>').join('');show(0);return{host,data,show,stop,get index(){return index;}};
}
globalThis.ProjectionPlayers=[];document.querySelectorAll('[data-pr-spec]').forEach(h=>ProjectionPlayers.push(mount(h,JSON.parse(h.dataset.prSpec))));
const form=document.querySelector('#pr-explorer');if(form){let current=null;form.onsubmit=e=>{e.preventDefault();const a=Number(form.elements.angle.value),b=[Number(form.elements.x.value),Number(form.elements.y.value)],w=[1,Number(form.elements.weight.value)];const out=document.querySelector('#pr-explorer-output');try{if(!Number.isFinite(a)||a<0||a>90||!b.every(v=>Number.isFinite(v)&&Math.abs(v)<=5)||!Number.isFinite(w[1])||w[1]<1||w[1]>5)throw Error('Use an angle from 0 through 90, coordinates from minus 5 through 5, and a vertical weight from 1 through 5.');current?.stop();const host=document.querySelector('[data-pr-spec]').cloneNode(true);host.querySelector('h3').textContent='Your line and declared metric';host.removeAttribute('data-pr-spec');out.replaceChildren(host);current=mount(host,{kind:'projection',u:[Math.cos(a*Math.PI/180),Math.sin(a*Math.PI/180)],b,w});globalThis.ProjectionExplorer=current;document.querySelector('#pr-error').textContent='';}catch(error){document.querySelector('#pr-error').textContent=error.message;}};form.dispatchEvent(new Event('submit',{cancelable:true}));}
